/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
for s in ['http://localhost/%3A5','http://localhost/#%3A10','http://localhost/%C3%B6/page_1?x=%3A10#%32-7','http://host3.com:8080/p']:
 u=QUrl(s)
 print(s)
 for part in ('host','path','query','fragment'):
  f=getattr(u,part)
  for mode in (QUrl.FullyEncoded,QUrl.PrettyDecoded):
   try: print(part,mode,f(mode))
   except TypeError: print(part,'no format',f()); break
 print('encoded',bytes(u.toEncoded()).decode())
PY"

