/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
u=QUrl('http://localhost/%3A5?x=%3A10#%3A10')
for mode in (QUrl.TolerantMode,QUrl.StrictMode,QUrl.DecodedMode):
 for part,setter in [('path','setPath'),('query','setQuery'),('fragment','setFragment')]:
  v=getattr(u,part)(QUrl.FullyEncoded)
  w=QUrl(u)
  try: getattr(w,setter)(v,mode); print(part,mode,bytes(w.toEncoded()).decode())
  except Exception as e: print(type(e).__name__,str(e))
PY"

